def parse_graph(inp, P, R, D, req):
    parse_states(req["states"], P, R, D)
    states = req["states"]
    n = len(states)
    edges = req["edges"]
    chk(isinstance(edges, list), "E_SCHEMA")
    if len(edges) > 60000:
        raise Err("E_LIMIT")
    elist = []
    names = set()
    seen_e = set()
    for e in edges:
        s, nm, t = parse_edge(e, n)
        key = (s, nm, t)
        chk(key not in seen_e, "E_SCHEMA")
        seen_e.add(key)
        names.add(nm)
        elist.append(key)
    fair = parse_fairness(req["fairness"])
    for a, m in fair:
        names.add(a)
    if len(names) > 64:
        raise Err("E_LIMIT")
    st = req["start"]
    if not isint(st):
        raise Err("E_SCHEMA")
    chk(0 <= st < n, "E_LIMIT")
    return states, elist, fair, names, st, n


def done_flags(states, P, R):
    dn = []
    for st in states:
        ok = True
        dl = st["delivered"]
        for r in range(P):
            if len(dl[r]) != R:
                ok = False
                break
        dn.append(ok)
    return dn


def state_is_safe(st, expected, inp, P, R, D):
    dl = st["delivered"]
    for r in range(P):
        arr = dl[r]
        for q in range(len(arr)):
            if arr[q] != expected[q]:
                return False
    for s in st["slots"]:
        tot = [0] * D
        seq = s["seq"]
        for r in s["ranks"]:
            vec = inp[r][seq]
            for i in range(D):
                tot[i] += vec[i]
        if s["sum"] != tot:
            return False
    return True


